CREATE DATABASE IF NOT EXISTS marketmind; USE marketmind;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlist(user_id INT NOT NULL,symbol VARCHAR(12) NOT NULL,PRIMARY KEY(user_id,symbol),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE alerts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,symbol VARCHAR(12) NOT NULL,type ENUM('above','below','pct') NOT NULL,value DECIMAL(14,4) NOT NULL,active TINYINT DEFAULT 1,triggered_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,kind VARCHAR(20) DEFAULT 'alert',message VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE portfolios(user_id INT PRIMARY KEY,initial DECIMAL(14,2) DEFAULT 10000,cash DECIMAL(14,2) DEFAULT 10000,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE holdings(user_id INT NOT NULL,symbol VARCHAR(12) NOT NULL,qty INT NOT NULL,avg_cost DECIMAL(14,4) NOT NULL,PRIMARY KEY(user_id,symbol),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,symbol VARCHAR(12),side ENUM('buy','sell'),qty INT,price DECIMAL(14,4),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
